export function minKnightMoves(x        , y        )         {
x=Math.abs(x);y=Math.abs(y);const q           =[[0,0,0]],seen=new Set        (["0,0"]),moves=[[1,2],[2,1],[-1,2],[-2,1],[1,-2],[2,-1],[-1,-2],[-2,-1]];for(let i=0;i<q.length;i++){const [a,b,d]=q[i];if(a===x&&b===y)return d;for(const [dx,dy] of moves){const nx=a+dx,ny=b+dy,key=nx+","+ny;if(nx>=-2&&ny>=-2&&nx<=x+2&&ny<=y+2&&!seen.has(key)){seen.add(key);q.push([nx,ny,d+1]);}}}throw new Error("unreachable");
}

